-- Add private register filters without changing the immutable ownership, audit,
-- concurrency, bounded collection or RLS guarantees of existing saved reports.
ALTER TABLE "SavedReport" ADD COLUMN "from" DATE, ADD COLUMN "to" DATE, ADD COLUMN status VARCHAR(24);
ALTER TABLE "SavedReport" DROP CONSTRAINT "SavedReport_kind_check";
ALTER TABLE "SavedReport" DROP CONSTRAINT "SavedReport_dateMode_check";
ALTER TABLE "SavedReport" DROP CONSTRAINT "SavedReport_check";
ALTER TABLE "SavedReport" ADD CONSTRAINT "SavedReport_kind_check" CHECK(kind IN('CUSTOMER_BALANCES','CUSTOMER_AGING','SUPPLIER_BALANCES','SUPPLIER_AGING','CUSTOMER_OVERDUE','SUPPLIER_OVERDUE','INVOICE_REGISTER','EXPENSE_REGISTER','QUOTE_REGISTER','SALES_ORDER_REGISTER','PURCHASE_ORDER_REGISTER'));
ALTER TABLE "SavedReport" ADD CONSTRAINT "SavedReport_dateMode_check" CHECK("dateMode" IN('FIXED','TODAY_UTC','PREVIOUS_MONTH_END_UTC','FIXED_RANGE','CURRENT_MONTH_UTC','PREVIOUS_MONTH_UTC'));
ALTER TABLE "SavedReport" ADD CONSTRAINT "SavedReport_filter_shape_check" CHECK (
 (kind IN('CUSTOMER_BALANCES','CUSTOMER_AGING','SUPPLIER_BALANCES','SUPPLIER_AGING','CUSTOMER_OVERDUE','SUPPLIER_OVERDUE') AND "from" IS NULL AND "to" IS NULL AND status IS NULL AND
  (("dateMode"='FIXED' AND "asOf" IS NOT NULL AND "asOf">='0001-01-01'::date AND "asOf"<='9999-12-31'::date) OR ("dateMode" IN('TODAY_UTC','PREVIOUS_MONTH_END_UTC') AND "asOf" IS NULL)))
 OR
 (kind IN('INVOICE_REGISTER','EXPENSE_REGISTER','QUOTE_REGISTER','SALES_ORDER_REGISTER','PURCHASE_ORDER_REGISTER') AND "asOf" IS NULL AND
  (("dateMode"='FIXED_RANGE' AND "from" IS NOT NULL AND "to" IS NOT NULL AND "from">='0001-01-01'::date AND "to"<='9999-12-31'::date AND "to">="from" AND "to"-"from"<366) OR ("dateMode" IN('CURRENT_MONTH_UTC','PREVIOUS_MONTH_UTC') AND "from" IS NULL AND "to" IS NULL)))
);
ALTER TABLE "SavedReport" ADD CONSTRAINT "SavedReport_status_check" CHECK(status IS NULL OR
 (kind='INVOICE_REGISTER' AND status IN('DRAFT','ISSUED','VOID')) OR
 (kind='EXPENSE_REGISTER' AND status IN('DRAFT','POSTED','VOID')) OR
 (kind='QUOTE_REGISTER' AND status IN('DRAFT','SENT','ACCEPTED','REJECTED')) OR
 (kind='SALES_ORDER_REGISTER' AND status IN('NEW','IN_PROGRESS','COMPLETED','CANCELLED')) OR
 (kind='PURCHASE_ORDER_REGISTER' AND status IN('DRAFT','ISSUED','RECEIVED','CANCELLED')));
